import React, { useEffect, useState } from "react";
import { supabase } from "../supabaseClient";
import { BarChart, Bar, XAxis, YAxis, Tooltip, PieChart, Pie, Cell, Legend, ResponsiveContainer } from "recharts";

const COLORS = ["#4CAF50", "#ff4d4d"]; // Vacant, Occupied

const Analytics = () => {
  const [slotData, setSlotData] = useState([]);
  const [overallData, setOverallData] = useState([]);

  useEffect(() => {
    fetchAnalytics();
    const interval = setInterval(fetchAnalytics, 5000); // refresh every 5 sec
    return () => clearInterval(interval);
  }, []);

  async function fetchAnalytics() {
    // Fetch all parking slots
    const { data: slots, error } = await supabase
      .from("parking_slots")
      .select("*");

    if (error) {
      console.log("Error fetching slots:", error);
      return;
    }

    // Prepare bar chart data for each slot
    const barData = slots.map(slot => ({
      slot: "Slot " + slot.slot,
      occupied: slot.status === "occupied" ? 1 : 0,
      vacant: slot.status === "vacant" ? 1 : 0,
    }));

    // Prepare pie chart data for overall occupancy
    const occupiedCount = slots.filter(s => s.status === "occupied").length;
    const vacantCount = slots.filter(s => s.status === "vacant").length;
    const pieData = [
      { name: "Vacant", value: vacantCount },
      { name: "Occupied", value: occupiedCount },
    ];

    setSlotData(barData);
    setOverallData(pieData);
  }

  return (
    <div style={{ padding: "20px", fontFamily: "Arial, sans-serif" }}>
      <h1>📊 Parking Analytics</h1>

      <h2>Slot Occupancy</h2>
      <ResponsiveContainer width="100%" height={300}>
        <BarChart data={slotData}>
          <XAxis dataKey="slot" />
          <YAxis />
          <Tooltip />
          <Legend />
          <Bar dataKey="occupied" fill="#ff4d4d" />
          <Bar dataKey="vacant" fill="#4CAF50" />
        </BarChart>
      </ResponsiveContainer>

      <h2 style={{ marginTop: "40px" }}>Overall Occupancy</h2>
      <ResponsiveContainer width="100%" height={250}>
        <PieChart>
          <Pie
            data={overallData}
            cx="50%"
            cy="50%"
            outerRadius={80}
            label
          >
            {COLORS.map((color, index) => (
              <Cell key={index} fill={color} />
            ))}
          </Pie>
          <Legend />
          <Tooltip />
        </PieChart>
      </ResponsiveContainer>
    </div>
  );
};

export default Analytics;
